#!/usr/bin/env python3
"""Generate testenv/fleet.yaml: a synthetic fleet with planted faults.

Everything here is invented. Cluster names are generic, the "ami-synth-*" ids
are fake, and faults are plain data fields (never code keyed on a name).

Usage: python3 testenv/gen_fleet.py > testenv/fleet.yaml
"""
import sys

import yaml

SRC, TARGET = "1.25", "1.26"

HEADER = """\
# Synthetic fleet for the upgrade safety simulator. GENERATED by testenv/gen_fleet.py.
# Edit the generator, not this file. Ground truth for the planted faults is the
# `faults:` list at the bottom; tests assert that every fault shows up in the data
# and is caught by exactly the step named in `expect_stop`.
"""


def cluster(name, stage, ctype, workers=5, db_nodes=None, flags=None):
    db_nodes = db_nodes or {}
    masters = []
    for i in (1, 2, 3):
        masters.append({
            "name": f"{name}-m{i}",
            "apiserver": SRC, "controller_manager": SRC, "scheduler": SRC, "kubelet": SRC,
            "ready": True, "readyz": True, "lb_member": "healthy",
            # behaviour of this master after its apiserver is upgraded
            "readyz_after_upgrade": True, "lb_after_upgrade": "healthy",
            "etcd_returns": True,
        })
    etcd = {
        "members": [{"name": f"{name}-m{i}", "online": True,
                     "raft_index": 1000500 - 40 * (i - 1)} for i in (1, 2, 3)],
        "leaders": [f"{name}-m1"],
    }
    nodes = []
    for i in range(1, workers + 1):
        nodes.append({
            "name": f"{name}-w{i}", "ami": "ami-synth-125", "kubelet": SRC, "ready": True,
            "db": db_nodes.get(i), "eviction_s": 40 + 10 * i,
        })
    pdbs = []
    for i, svc in sorted(db_nodes.items()):
        pdbs.append({"name": f"{svc}-pdb", "workload": svc, "nodes": [f"{name}-w{i}"],
                     "min_available": 2, "current_healthy": 3})
    return {
        "name": name, "stage": stage, "cluster_type": ctype, "version": SRC,
        "flags": {"drain_timeout_s": 300, **(flags or {})},
        "masters": masters,
        "etcd": etcd,
        "workers": {
            "asg": {"name": f"{name}-workers", "ami": "ami-synth-125", "desired": workers,
                    "launch_template": {"id": f"lt-{name}", "version": 7, "ami": "ami-synth-125",
                                        "instance_type": "m5.xlarge", "volume_gb": 100}},
            "nodes": nodes,
        },
        "pdbs": pdbs,
        "addons": {
            "ccm": {"version": SRC, "healthy": True, "target_rollout_healthy": True},
            "cni": {"version": SRC, "healthy": True, "max_unavailable": 1, "target_rollout_healthy": True},
            "cluster_autoscaler": {"version": SRC, "healthy": True, "target_rollout_healthy": True},
        },
        "kube_system": {"pods_total": 14, "pods_running": 14},
        "workload": {
            "pods_total": 60, "pods_running": 60,
            "critical_services": [{"name": "edge-gateway", "reachable": True},
                                  {"name": "ingest-api", "reachable": True}],
        },
        "external": {"alerts": []},
        "monitor": {"nodes_ready": 3 + workers, "etcd_members_up": 3},
    }


def build():
    dev = cluster("dev-1", "dev", "dev-staging", workers=3)

    preprod = cluster("preprod-1", "preprod", "dev-staging", workers=4, db_nodes={1: "mysql"},
                      flags={"drain_timeout_s": 600})
    preprod["workers"]["nodes"][1]["eviction_s"] = 540          # slow, but the 600 s flag covers it

    canary = cluster("prod-canary", "prod-canary", "workload", workers=5,
                     db_nodes={1: "kafka", 2: "mysql"}, flags={"drain_timeout_s": 600})
    canary["workers"]["nodes"][3]["eviction_s"] = 420

    east = cluster("prod-east", "prod", "workload", workers=5, db_nodes={1: "kafka"})
    east["etcd"]["members"][2]["raft_index"] = 1000500 - 2000   # F1: follower 2000 behind

    west = cluster("prod-west", "prod", "workload", workers=5, db_nodes={1: "mysql"})
    west["pdbs"][0]["min_available"] = 3                        # F3: allows zero disruptions
    west["pdbs"][0]["current_healthy"] = 3

    south = cluster("prod-south", "prod", "workload", workers=5, db_nodes={1: "kafka"})
    south["addons"]["ccm"]["target_rollout_healthy"] = False    # F2: new CCM does not roll out

    eu = cluster("prod-eu", "prod", "workload", workers=5, db_nodes={1: "mysql"})
    eu["workers"]["nodes"][2]["eviction_s"] = 540               # F4: slow, no 600 s flag

    north = cluster("prod-north", "prod", "workload", workers=5, db_nodes={1: "kafka"})
    north["masters"][1]["readyz_after_upgrade"] = False         # F5: second master's apiserver never ready
    north["masters"][1]["lb_after_upgrade"] = "unhealthy"

    mgmt = cluster("mgmt-1", "management", "management", workers=4, db_nodes={1: "mysql"})

    faults = [
        {"id": "F1", "cluster": "prod-east", "kind": "raft_lag",
         "what": "one etcd follower is 2000 entries behind the leader",
         "expect_stop": "check", "criterion": "etcd_raft_lag"},
        {"id": "F2", "cluster": "prod-south", "kind": "ccm_unhealthy",
         "what": "the target cloud-controller-manager rollout is unhealthy (would strand new workers on the uninitialized taint)",
         "expect_stop": "addon:ccm"},
        {"id": "F3", "cluster": "prod-west", "kind": "pdb_blocks_drain",
         "what": "a stateful node's PDB allows zero disruptions",
         "expect_stop": "workers:batch1"},
        {"id": "F4", "cluster": "prod-eu", "kind": "slow_eviction",
         "what": "a node evicts in 540 s but the cluster has no drain_timeout_s=600 flag",
         "expect_stop": "workers:batch"},
        {"id": "F5", "cluster": "prod-north", "kind": "apiserver_not_ready",
         "what": "second master's apiserver fails /readyz and LB membership after upgrade",
         "expect_stop": "master:prod-north-m2:apiserver_ready"},
    ]
    return {
        "fleet": {"source_version": SRC, "target_version": TARGET,
                  "stage_order": ["dev", "preprod", "prod-canary", "prod", "management"]},
        "amis": {"ami-synth-125": {"kubelet": "1.25"}, "ami-synth-126": {"kubelet": "1.26"}},
        "clusters": [dev, preprod, canary, east, west, south, eu, north, mgmt],
        "faults": faults,
    }


if __name__ == "__main__":
    sys.stdout.write(HEADER)
    yaml.safe_dump(build(), sys.stdout, sort_keys=False, default_flow_style=False, width=100)
